using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize input data, matching the original C semantics.
 *
 * Original C:
 *   *alpha = 1.5;
 *   *beta  = 1.2;
 *   for i in [0, n):
 *     x[i] = (i % n) / n;
 *     for j in [0, n):
 *       A[i][j] = ((i*j+1) % n) / n;
 *       B[i][j] = ((i*j+2) % n) / n;
 *
 * C arrays are row-major: A[i][j] with j varying fastest.
 * Halide buffers are column-major in terms of indices (first dimension
 * varies fastest), so we map:
 *   C  A[i][j]  ->  Halide A(j, i)
 *   C  B[i][j]  ->  Halide B(j, i)
 *   C  x[i]     ->  Halide x(i)
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_x("init_x"), init_A("init_A"), init_B("init_B");

    // x[i] = (i % n) / n;
    init_x(i) = cast<num_t>((i % n)) / cast<int>(n);

    // A[i][j] = ((i*j+1) % n) / n;  ->  A(j, i)
    init_A(j, i) = cast<num_t>(((i * j + 1) % n)) / cast<int>(n);

    // B[i][j] = ((i*j+2) % n) / n;  ->  B(j, i)
    init_B(j, i) = cast<num_t>(((i * j + 2) % n)) / cast<int>(n);

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size (from gesummv.hpp / PolyBench)
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   A, B : N x N (Halide indices: (j, i) == C's [i][j])
    //   x, y : length N (Halide index: (i) == C's [i])
    Halide::Buffer<num_t, 2> A_buf(n, n);
    Halide::Buffer<num_t, 2> B_buf(n, n);
    Halide::Buffer<num_t, 1> x_buf(n);
    Halide::Buffer<num_t, 1> y_buf(n);

    // ImageParams for inputs to the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data (fills A_buf, B_buf, x_buf, and sets alpha/beta)
    init_array(n, &alpha, &beta, A_buf, B_buf, x_buf);

    // Halide algorithm: GESUMMV
    //
    // Original kernel:
    //   for i in [0, N):
    //     tmp[i] = 0;
    //     y[i]   = 0;
    //     for j in [0, N):
    //       tmp[i] += A[i][j] * x[j];
    //       y[i]   += B[i][j] * x[j];
    //     y[i] = alpha * tmp[i] + beta * y[i];
    //
    // We express this as:
    //   tmp(i) = sum_j A(i,j)*x(j)
    //   y_acc(i) = sum_j B(i,j)*x(j)
    //   gesummv(i) = alpha * tmp(i) + beta * y_acc(i)
    //
    // With our mapping A(j,i) == A[i][j] and B(j,i) == B[i][j].

    Var i("i");
    RDom j(0, n, "j");

    Func tmp("tmp"), y_acc("y_acc"), gesummv("gesummv");

    // Initialize reductions
    tmp(i)   = cast<num_t>(0);
    y_acc(i) = cast<num_t>(0);

    // Reduction over j: tmp(i) += A[i][j]*x[j]; y_acc(i) += B[i][j]*x[j];
    tmp(i)   += A_param(j, i) * x_param(j);
    y_acc(i) += B_param(j, i) * x_param(j);

    // Final combination: y[i] = alpha * tmp[i] + beta * y[i];
    gesummv(i) = Expr(alpha) * tmp(i) + Expr(beta) * y_acc(i);

    // Bind ImageParams to concrete buffers
    A_param.set(A_buf);
    B_param.set(B_buf);
    x_param.set(x_buf);

    // JIT-compile the kernel
    gesummv.compile_jit();

    // Time the kernel execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: compute y_buf
    gesummv.realize(y_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (to help prevent dead-code elimination)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ++ii) {
            std::cerr << y_buf(ii) << '\n';
        }
    }

    // Print execution time in seconds (similar to PolyBench timing output)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
