 * (column-major indexing in the first dimension).
 */
static void init_array(int n,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 1> x) {
