    // A[i][j] = (DATA_TYPE)((i*j+1) % n) / n;
    // Map to A(j, i).
    init_A(j, i) = cast<num_t>(((i * j + 1) % n)) / cast<int>(n);

    // B[i][j] = (DATA_TYPE)((i*j+2) % n) / n;
    // Map to B(j, i).
    init_B(j, i) = cast<num_t>(((i * j + 2) % n)) / cast<int>(n);

    // Realize into the provided buffers.
    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size (compile-time constant from PolyBench).
    int n = N;

    // Scalars.
    num_t alpha;
    num_t beta;

    // Buffers corresponding to:
    //   A[N][N], B[N][N], x[N], y[N]
    //
    // Mapping: C's A[i][j] -> A(j, i), etc.
    Halide::Buffer<num_t, 2> A(n, n);  // (j, i)
    Halide::Buffer<num_t, 2> B(n, n);  // (j, i)
    Halide::Buffer<num_t, 1> x(n);     // (i)
    Halide::Buffer<num_t, 1> y(n);     // (i)

    // Initialize data as in the original C code.
    init_array(n, &alpha, &beta, A, B, x);

    // ImageParams for the inputs to the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Halide implementation of kernel_gesummv:
    //
    // for (i = 0; i < N; i++) {
    //   tmp[i] = 0;
    //   y[i]   = 0;
    //   for (j = 0; j < N; j++) {
    //     tmp[i] = A[i][j] * x[j] + tmp[i];
    //     y[i]   = B[i][j] * x[j] + y[i];
    //   }
    //   y[i] = alpha * tmp[i] + beta * y[i];
    // }
    //
    // This is:
    //   tmp = A * x
    //   y   = B * x
    //   y   = alpha * tmp + beta * y
    //
    // We'll implement:
    //   tmp(i)    = sum_j A[i][j] * x[j]
    //   y_accum(i)= sum_j B[i][j] * x[j]
    //   gesummv(i)= alpha * tmp(i) + beta * y_accum(i)

    Var i("i");
    // Use the width of A (number of columns) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");  // r corresponds to j

    Func tmp("tmp");
    Func y_accum("y_accum");
    Func gesummv("gesummv");

    // Initialize tmp[i] = 0, y_accum[i] = 0.
    tmp(i)     = cast<num_t>(0);
    y_accum(i) = cast<num_t>(0);

