    // y[i]   += B[i][j] * x[j];
    //
    // Recall A[i][j] -> A_param(j, i), B[i][j] -> B_param(j, i), x[j] -> x_param(j).
    tmp(i)     += A_param(r, i) * x_param(r);
    y_accum(i) += B_param(r, i) * x_param(r);

    // Final combination: y[i] = alpha * tmp[i] + beta * y[i].
    gesummv(i) = Expr(alpha) * tmp(i) + Expr(beta) * y_accum(i);

    // Simple schedule reflecting the original structure:
    // compute tmp and y_accum fully, then compute gesummv.
    tmp.compute_root();
    y_accum.compute_root();
    gesummv.compute_root();

    // JIT-compile the pipeline.
    gesummv.compile_jit();

    // Measure execution time for a single realization, similar to PolyBench timing.
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into y.
