/**
 * Initialize arrays A, B, and x following the original C kernel's init_array().
 *
 * C layout:
 *   A[i][j], B[i][j] with i = row, j = column (row-major)
 *
 * Halide layout:
 *   Buffer A(j, i), B(j, i)  (column-major in memory, but with consistent indexing)
 *   Buffer x(i)
 */
static
void init_array(int n,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 1> x) {

    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    // Initialize x[i] = (i % n) / n
    Func init_x("init_x");
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // Map A[i][j] -> A(j, i)
    Func init_A("init_A");
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // Map B[i][j] -> B(j, i)
    Func init_B("init_B");
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}


