    // Problem size (from gesummv.hpp / PolyBench)
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the original C arrays:
    //   A[N][N], B[N][N], tmp[N], x[N], y[N]
    //
    // For 2D arrays A[i][j], B[i][j] we use Buffer(j, i) as in the gemm example.
    Halide::Buffer<num_t, 2> A(n, n);   // A(j, i)
    Halide::Buffer<num_t, 2> B(n, n);   // B(j, i)
    Halide::Buffer<num_t, 1> tmp(n);    // tmp[i] (not strictly needed by the Halide kernel)
    Halide::Buffer<num_t, 1> x(n);      // x[i]
    Halide::Buffer<num_t, 1> y(n);      // y[i], output

    // Initialize input data
    init_array(n, &alpha, &beta, A, B, x);

    // Wrap inputs in ImageParams so the Halide Func can access them
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // ------------------------------------------------------------------------
    // Halide implementation of kernel_gesummv
    //
    // Original kernel:
    //
    // for (i = 0; i < N; i++) {
    //   tmp[i] = 0;
    //   y[i]   = 0;
    //   for (j = 0; j < N; j++) {
    //     tmp[i] = A[i][j] * x[j] + tmp[i];
    //     y[i]   = B[i][j] * x[j] + y[i];
    //   }
    //   y[i] = alpha * tmp[i] + beta * y[i];
    // }
    //
    // We express this as:
    //   tmp(i)    = sum_j A[i][j] * x[j]
    //   y_accum(i)= sum_j B[i][j] * x[j]
    //   gesummv(i)= alpha * tmp(i) + beta * y_accum(i)
    // ------------------------------------------------------------------------

    Var i("i");
    RDom j(0, A.dim(0).extent(), "j");  // j iterates over columns (first dimension of A)

    Func tmp_func("tmp_func");
    Func y_accum("y_accum");
    Func gesummv("gesummv");

    // Initialize tmp[i] and y_accum[i] to zero
    tmp_func(i)   = cast<num_t>(0);
    y_accum(i)    = cast<num_t>(0);

    // Reductions over j:
    // tmp[i]    += A[i][j] * x[j]
    // y_accum[i]+= B[i][j] * x[j]
    //
    // Remember: A[i][j] is stored as A_param(j, i) and B[i][j] as B_param(j, i).
    tmp_func(i)   += A_param(j, i) * x_param(j);
    y_accum(i)    += B_param(j, i) * x_param(j);

    // Final combination:
    // y[i] = alpha * tmp[i] + beta * y[i]
    gesummv(i) = Halide::Expr(alpha) * tmp_func(i) +
                 Halide::Expr(beta)  * y_accum(i);

    // ------------------------------------------------------------------------
    // Schedule
    //
    // We compute gesummv at the root. For each output element i, tmp_func and
    // y_accum are computed as needed, which roughly mirrors the original
    // loop nest (outer i, inner j).
    // ------------------------------------------------------------------------

    gesummv.compute_root();
    tmp_func.compute_at(gesummv, i);
    y_accum.compute_at(gesummv, i);

    // JIT-compile the pipeline
    gesummv.compile_jit();

    // ------------------------------------------------------------------------
    // Execute and time the kernel
    // ------------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: write into y
    gesummv.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print results (similar spirit to PolyBench's print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
