    *beta  = (num_t)1.2;

    Var i("i"), j("j");

    Func init_x("init_x"), init_A("init_A"), init_B("init_B");

    // x[i] = (i % n) / n
    init_x(i) = cast<num_t>(i % n) / cast<int>(n);

    // A[i][j] = ((i*j + 1) % n) / n   -> A(j, i)
    init_A(j, i) = cast<num_t>((i * j + 1) % n) / cast<int>(n);

    // B[i][j] = ((i*j + 2) % n) / n   -> B(j, i)
    init_B(j, i) = cast<num_t>((i * j + 2) % n) / cast<int>(n);

    init_x.realize(x);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C arrays A[n][n], B[n][n] are mapped to Buffers of shape (n, n),
    // with access A(j, i), B(j, i) corresponding to A[i][j], B[i][j].
    Halide::Buffer<num_t, 2> A(n, n);
    Halide::Buffer<num_t, 2> B(n, n);

    // C arrays x[n], y[n] map directly to 1D Buffers.
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> y(n);

    // Halide input parameters
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Initialize data
    init_array(n, &alpha, &beta, A, B, x);

    // Bind Buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    x_param.set(x);

    // Vars and reduction domain
    Var i("i");
    // Reduction over j corresponds to the inner loop in the original C code.
    RDom j(0, A.dim(0).extent(), "j");

    // tmp[i] and y_acc[i] correspond to the intermediate arrays in C:
    //
    //   tmp[i] = 0;
    //   y[i]   = 0;
    //   for (j = 0; j < n; j++) {
    //       tmp[i] += A[i][j] * x[j];
    //       y[i]   += B[i][j] * x[j];
    //   }
    //
    Func tmp_f("tmp_f"), y_acc("y_acc"), gesummv("gesummv");

    // Initialization (pure definitions)
    tmp_f(i) = cast<num_t>(0);
    y_acc(i) = cast<num_t>(0);

    // Reduction updates: note index mapping A(i,j) -> A_param(j, i)
    tmp_f(i) += A_param(j, i) * x_param(j);
    y_acc(i) += B_param(j, i) * x_param(j);

    // Final combination:
    //   y[i] = alpha * tmp[i] + beta * y[i];
    gesummv(i) = Expr(alpha) * tmp_f(i) + Expr(beta) * y_acc(i);

    // JIT-compile the pipeline
    gesummv.compile_jit();

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: compute y
    gesummv.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump result (similar to print_array in PolyBench).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; ++idx) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print timing in seconds (like the gemm.cpp example)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
